function o(){const t=document.getElementById("css:lazy");if(t){const e=document.createElement("style");e.id="css:lazy-active",e.textContent=t.textContent,document.head.appendChild(e)}}function r(t){document.querySelectorAll(t).forEach(e=>{Array.from(e.getElementsByTagName("script")).forEach(n=>{const a=document.createElement("script");Array.from(n.attributes).forEach(c=>a.setAttribute(c.name,c.value)),a.text=n.textContent||"",n.parentNode?.replaceChild(a,n)})})}export{o as activateLazyStyles,r as loadScripts};
